    "situation": "杰西·伊莎贝尔·普莱斯（Jessie Isabelle Price，1930年1月1日至2015年11月12日）是一位兽医微生物学家。她分离并重现了 20 世纪 50 年代养鸭业最常见的危及生命疾病的病因，并开发了针对这种疾病和其他禽类疾病的疫苗。",
