    "born": "1950年代",
    "identity": "美国生物学家。Jennifer Lippincott-Schwartz 是霍华德休斯医学研究所珍妮莉亚研究园的高级组长，也是珍妮莉亚神经细胞生物学项目的创始成员。",
    "visibility": "较少被看见",
    "turnAge": 41,
    "situation": "詹妮弗·利平科特·施瓦茨 (Jennifer Lippincott-Schwartz) 是霍华德休斯医学研究所珍妮莉亚研究园区的高级组长，也是珍妮莉亚神经细胞生物学项目的创始成员。此前，1993 年至 2016 年，她曾担任美国国立卫生研究院尤尼斯·肯尼迪·施赖弗国家儿童健康和人类发展研究所细胞生物学和代谢项目细胞器生物学科的科长。",
    "resources": "公开职业身份包括生物学家；出生地记录为曼哈頓。",
    "protect": "保留她在生物学家领域中已经发生并可被核对的贡献。",
    "action": "此前，她于 1993 年至 2016 年期间担任美国国立卫生研究院尤尼斯·肯尼迪·施赖弗国家儿童健康和人类发展研究所校内研究部细胞生物学和代谢项目细胞器生物学科的主任。利平科特-施瓦茨在约翰·霍普金斯大学获得博士学位，并与理查德·克劳斯纳一起在贝塞斯达的 NICHD、NIH 进行博士后培训。马里兰州。 Lippincott-Schwartz 的研究表明，真核细胞的细胞器是动态的、自组织的结构，可以通过细胞内囊泡运输不断地自我再生，而不是静态的结构。",
    "outcome": "这些蛋白质使用多种活细胞成像技术（例如 FRAP、FCS 和光活化）进行标记。 Lippincott-Schwartz 将她最近的实验室研究致力于光活化定位显微镜（PALM），它可以在纳米尺度上观察高密度的分子分布。",
