    "turnAge": 38,
    "situation": "Adelle Lutz (born November 13, 1948) is an American artist, designer and actress, most known for work using unconventional materials and strategies to explore clothing as a communicative medium. She first gained attention for the surreal \"Urban Camouflage\" costumes featured in David Byrne's film True Stories (1986).",
    "resources": "公开职业身份包括演員、劇裝設計、電影導演、導演、模特儿；出生地记录为纽约。",
