    "action": "She first gained attention for the surreal \"Urban Camouflage\" costumes featured in David Byrne's film True Stories (1986). She has designed costumes for film director Susan Seidelman, theater directors Robert Wilson and JoAnne Akalaitis, and musicians including Byrne, Bono and Michael Stipe. In the 1990s, she began to shift from costume to sculpture, installation art and eventually, performance.",
    "outcome": "Her work has also been featured in The New York Times, Harper's Magazine, Newsweek, Village Voice, Vanity Fair and Paper and in books on fashion, costume and public art, including Fashion and Surrealism (1987), Designed for Delight (1997), Twenty Years of Style: The World According to Paper (2004), and Because Dreaming is Best Done in Public: Creative Time in Public Spaces (2012). Her work Ponytail Boot (2002) is part of the Metropolitan Museum of Art collection.",
    "cost": "当前公开来源没有足够材料说明她个人承担的代价；不据此推断未公开的感受、动机或关系经历。",
