    "identity": "美国作家、艺术史学家、策展人和摄影师。克里斯蒂娜·里奥·鲁塞尔（Christine Leo Roussel，原姓克里斯蒂娜·里奥；1939年1月20日至2026年7月中旬）是一位美国作家、艺术史学家、策展人、摄影师和顾问。",
    "visibility": "较少被看见",
    "turnAge": 81,
    "situation": "克里斯蒂娜·里奥·鲁塞尔（Christine Leo Roussel，原姓克里斯蒂娜·里奥；1939年1月20日至2026年7月中旬）是一位美国作家、艺术史学家、策展人、摄影师和顾问。她在大都会艺术博物馆的托马斯·霍文（Thomas Hoving）手下工作，然后创建了自己的工作室“罗塞尔艺术保护”（Roussel Art Conservation）。",
    "resources": "公开职业包括身份摄影师、策展人、艺术史学家；出生地记录为纽约。",
    "protect": "保留她在摄影师领域中已经发生并可被核对的贡献。",
    "action": "她在大都会艺术博物馆的托马斯·霍文（Thomas Hoving）手下工作，然后创建了自己的工作室“罗塞尔艺术保护”（Roussel Art Conservation）。她因其对家乡纽约市艺术品的了解而闻名，并专门从事雕塑保护工作。她是纳尔逊·洛克菲勒的助手，也是《洛克菲勒中心的艺术》一书的作者，该书详细介绍了洛克菲勒中心内所有作品的历史。",
    "outcome": "她因其对家乡纽约市艺术品的了解而闻名，并专门从事雕塑保护工作。她是纳尔逊·洛克菲勒的助手，也是《洛克菲勒中心的艺术》一书的作者，该书详细介绍了洛克菲勒中心内所有作品的历史。",
