    "situation": "伊莎贝拉·柯克兰（Isabella Kirkland，1954 年出生）是一位美国视觉艺术家和生物多样性研究员。她以跨越艺术史、自然科学和生态行动主义的复杂、具代表性的绘画而闻名。",
