    "identity": "艺术家（生于 1964 年）。露丝·帕斯汀（Ruth Pastine，生于 1964 年）是一位美国艺术家，以探索色彩、光线和空间的现象学体验的抽象极简主义绘画而闻名。",
    "visibility": "较少被看见",
    "turnAge": "公开生平阶段",
    "situation": "露丝·帕斯汀（Ruth Pastine，生于 1964 年）是一位美国艺术家，以探索色彩、光线和空间的现象学体验的抽象极简主义绘画而闻名。评论家将她的艺术与南加州光与空间运动联系起来，同时指出了关键的区别，例如它对意识的形而上学方面的关注以及对基本传统手段（画笔、油漆、粉彩）而不是合成工业材料的依赖。",
    "resources": "公开职业身份包括艺术家；出生地记录为纽约。",
    "protect": "保留她在艺术家领域中已经发生并可被核对的贡献。",
    "action": "评论家将她的艺术与南加州光与空间运动联系起来，同时指出了关键的区别，例如它对意识的形而上学方面的关注以及对基本传统手段（画笔、油漆、粉彩）而不是合成工业材料的依赖。在这些方面，作家们将她的艺术血统追溯到莫奈和马列维奇——他们试图捕捉光的不可言喻——以及抽象表现主义和色域画家，如巴尼特·纽曼、阿德·莱因哈特和马克·罗斯科，他们探索了油画的色彩和色调的细微差别。帕斯廷的画作通常由无缝的渐变带或色域组成，这些色带或色域以无数的笔触分层构建，它们在光学上结合在一起，看起来像背光一样脉动、漂浮、溶解或发光。",
    "outcome": "她的作品被 SFMOMA、休斯顿美术馆、菲利普斯收藏馆和笛扬博物馆等公共收藏。她在南加州生活和工作。",
