    "situation": "Linda Alterwitz (born 1960) is an American visual artist whose work Integrates art, science and technology, investigating the inner workings of the human body and its connection to the natural world and cosmos. Her practice includes photographic and collaged works, immersive installations and participatory methods, and employs alternative imaging devices ranging from low-tech plastic cameras to advanced medical diagnostic machines.",
