    "action": "Her practice includes photographic and collaged works, immersive installations and participatory methods, and employs alternative imaging devices ranging from low-tech plastic cameras to advanced medical diagnostic machines. Her complex images frequently superimpose medical visualizations (x-rays, MRI scans, thermographic images) onto abstracted portraits and landscapes, blurring distinctions between the outer body, its underlying systems and organs, and the external environment. Alterwitz has exhibited at institutions including the New Mexico Museum of Art, Lancaster Museum of Art and History (MOAH), Mayo Clinic Florida, Aberystwyth Arts Centre (Wales), Barrick Museum of Art, and Lilley Museum of Art.",
