    "situation": "帕文·琼·库马尔夫人（Dame Parveen June Kumar，1942 年 6 月 1 日出生）是一位英裔印度医生，是巴茨和伦敦医学和牙科学院的医学和教育学教授。她在 NHS 工作了 40 多年，担任巴茨医院、伦敦医院和荷默顿大学医院的胃肠病学顾问和医生。",
