    "visibility": "较少被看见",
    "turnAge": 31,
    "situation": "Ionia Rollin Whipper (September 8, 1872 – April 13, 1953) was an American obstetrician and public health outreach worker. A 1903 graduate of Howard University School of Medicine, she was one of the few African-American women physicians of her generation.",
