    "protect": "保留她在医生领域中已经发生并可被核对的贡献。",
    "action": "A 1903 graduate of Howard University School of Medicine, she was one of the few African-American women physicians of her generation. During the mid-1920s, she worked for the United States Children's Bureau; her work there involved traveling the rural South and training midwives to use sterile delivery techniques and to register births. During a time when maternity homes for unwed mothers were for white women only, she opened her home to unwed mothers of color.",
    "outcome": "During a time when maternity homes for unwed mothers were for white women only, she opened her home to unwed mothers of color. Eventually, with the help of donations, she established a separate home for her work with these women, which still bears her name.",
