    "situation": "迪尼格尔·伊拉木江（维吾尔语：德克兰·伊拉木江，2001年5月3日－），又名迪妮格尔·衣拉木江，中国越野滑雪运动员。她是来自新疆阿勒泰市的维吾尔族人，是第一位在国际滑雪联合会项目上获得奖牌的中国越野滑雪运动员。",
