    "identity": "香港政治家。王䓪鸣女爵士（中文：王䓪鸣，1952年8月15日出生）又名谭耀明，前夫婚姻于1979年持续至1992年，1997年以后在公众场合主要称为黄耀珊博士，是香港社会工作行政人员和政治家，自2007年起出任香港青年协会执行董事。 1980年。",
    "visibility": "较少被看见",
    "turnAge": 27,
    "situation": "王䓪鸣女爵士（中文：王䓪鸣，1952年8月15日出生）亦名罗姗娜·谭黄益明，前夫于1979年结婚至1992年，1997年起在公众场合主要称为黄医生，是香港社会工作行政人员及政治家，自1980年起出任香港青年协会执行董事。香港主权移交前，她于1985年至1991年获委任为立法会非官守议员，并于1988年至1991年获委任为行政会议非官守议员。",
    "resources": "公开职业身份包括政治人物、太平紳士；出生地记录为英屬香港。",
