    "action": "香港主权移交前，她于1985年至1991年获委任为立法会非官守议员，并于1988年至1991年获委任为行政会议。她于1991年短暂退出政坛，但于1992年再次出任非官守行政议员，并于次年获委任为香港房屋委员会主席。黄氏深受最后一任英国殖民香港总督彭定康（后称勋爵）信任，于1995年选她接替邓男爵出任行政会议召集人（相当于行政会议高级非官守议员），成为殖民地政府末年的影响力人物。",
    "outcome": "此外，黄先生在香港商界也发挥着重要作用。她自1996年起担任香港上海汇丰银行非执行董事，并自2001年起担任李嘉诚爵士旗下长江实业的独立非执行董事。",
