    "visibility": "较少被看见",
    "turnAge": 61,
    "situation": "Wang Lixia（中文：王莉霞；拼音：Wáng Lìxiá；蒙古文：ᠸᠠᠩᠯᠢᠰᠢᠶᠠ；生于1964年6月）是出生于辽宁省建平县的中国蒙古族政治人物。她是中国共产党（CCP）党员，毕业于辽宁大学经济统计专业，获陕西财经学院（现西安交通大学经济与金融学院）经济学硕士学位，并获厦门大学经济学博士学位。",
    "resources": "公开职业身份包括政治人物；出生地记录为建平县。",
