    "action": "她是中国共产党（CCP）党员，毕业于辽宁大学经济统计专业，获陕西财经学院（现西安交通大学经济与金融学院）经济学硕士学位，并获厦门大学经济学博士学位。她来自学术界，后来历任多项政治职务，包括陕西省统计局局长、铜川市市长、陕西省副省长、中共内蒙古自治区委员会常务委员及统战部部长、中共呼和浩特市委员会书记。此后，她担任内蒙古自治区党委副书记、内蒙古自治区人民政府主席。",
